package com.sendmefile77.gamebroth.probe;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import android.text.format.DateFormat;
import android.util.LruCache;
import org.json.*;
import java.io.*;
import java.util.*;

/** Native gallery/archive/command UI. Opening a panel never navigates the game. */
final class PlayerPanel {
  private static final int SAVE_IMAGE=81,SAVE_ARCHIVE=82;
  private final PlayerController c;
  private final MainActivity a;
  private final Set<Dialog> dialogs=new HashSet<>();
  private final LruCache<String,Bitmap> thumbs=new LruCache<String,Bitmap>(8*1024*1024){@Override protected int sizeOf(String key,Bitmap b){return b.getByteCount();}};
  private Dialog reader;
  private PlayerStore.Scene reading;
  private boolean closed;
  PlayerPanel(PlayerController controller){c=controller;a=c.activity;}
  private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}
  private void ui(Runnable work){a.runOnUiThread(()->{if(!closed&&!a.isFinishing()&&!a.isDestroyed())work.run();});}
  private <T extends Dialog>T track(T d){dialogs.add(d);d.setOnDismissListener(x->dialogs.remove(d));return d;}
  private TextView text(String value,int size){TextView t=new TextView(a);t.setText(value);t.setTextSize(size);t.setTextColor(Color.rgb(236,232,224));t.setPadding(dp(12),dp(8),dp(12),dp(8));return t;}
  private Button button(String label,Runnable action){Button b=new Button(a);b.setText(label);b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());return b;}
  private LinearLayout column(){LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(23,27,31));return root;}
  void show(){String[] labels={"Галерея APK","Архив сцен","Быстрые команды","Сохранить текущую сцену",c.busy()?"Ожидание в фоне: активно":"Ждать в фоне вручную","Настройки панели"};
    track(new AlertDialog.Builder(a).setTitle("Панель APK").setItems(labels,(d,n)->{switch(n){case 0:gallery();break;case 1:archive();break;case 2:commands();break;case 3:c.capture();break;case 4:c.holdManually();break;case 5:settings();break;}}).setNegativeButton("Закрыть",null).create()).show();}
  private Dialog full(String title,LinearLayout content){Dialog d=track(new Dialog(a));LinearLayout root=column(),bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);TextView heading=text(title,18);bar.addView(heading,new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Закрыть",d::dismiss));root.addView(bar);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));root.setOnApplyWindowInsetsListener((view,insets)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout()),ime=insets.getInsets(android.view.WindowInsets.Type.ime());view.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));}else view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});d.setContentView(root);d.show();Window w=d.getWindow();if(w!=null){if(android.os.Build.VERSION.SDK_INT>=30)w.setDecorFitsSystemWindows(false);w.setLayout(-1,-1);root.requestApplyInsets();w.setBackgroundDrawableResource(android.R.color.transparent);}return d;}
  void gallery(){String page=c.game();c.io.execute(()->{List<PlayerStore.Picture> photos=c.store.pictures(page);ui(()->{LinearLayout root=column();if(photos.isEmpty()){root.addView(text("Здесь появятся иллюстрации открытой игры. Для ручного сохранения используйте «Сохранить текущую сцену».",16));full("Галерея APK",root);return;}
      GridView grid=new GridView(a);grid.setNumColumns(GridView.AUTO_FIT);grid.setColumnWidth(dp(145));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setVerticalSpacing(dp(8));grid.setHorizontalSpacing(dp(8));grid.setPadding(dp(8),dp(8),dp(8),dp(8));
      grid.setAdapter(new BaseAdapter(){public int getCount(){return photos.size();}public Object getItem(int p){return photos.get(p);}public long getItemId(int p){return p;}public View getView(int position,View old,android.view.ViewGroup parent){ImageView image=old instanceof ImageView?(ImageView)old:new ImageView(a);PlayerStore.Picture p=photos.get(position);image.setLayoutParams(new AbsListView.LayoutParams(-1,dp(180)));image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(Color.rgb(37,42,47));image.setContentDescription(p.caption.isEmpty()?"Иллюстрация "+(position+1):p.caption);image.setTag(p.id);Bitmap cached=thumbs.get(p.id);image.setImageBitmap(cached);if(cached==null)c.io.execute(()->{Bitmap b=decode(c.store.imageFile(p.id),320);if(b!=null)thumbs.put(p.id,b);ui(()->{if(p.id.equals(image.getTag()))image.setImageBitmap(b);});});return image;}});
      grid.setOnItemClickListener((v,item,n,id)->picture(photos,n,page));root.addView(grid,new LinearLayout.LayoutParams(-1,-1));full("Галерея · "+photos.size(),root);
    });});}
  private static Bitmap decode(File file,int bound){BitmapFactory.Options dimensions=new BitmapFactory.Options();dimensions.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),dimensions);if(dimensions.outWidth<=0||dimensions.outHeight<=0)return null;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=1;while(Math.max(dimensions.outWidth,dimensions.outHeight)/o.inSampleSize>bound)o.inSampleSize*=2;return BitmapFactory.decodeFile(file.getPath(),o);}
  private void picture(List<PlayerStore.Picture> photos,int start,String page){if(photos.isEmpty())return;int[] position={start};LinearLayout root=column(),actions=new LinearLayout(a);TextView caption=text("",14);final ZoomImageView[] holder=new ZoomImageView[1];ZoomImageView image=new ZoomImageView(a,delta->{int next=position[0]+delta;if(next>=0&&next<photos.size()){position[0]=next;showPicture(holder[0],caption,photos,position[0]);}});
    // The holder is local to this viewer; callbacks never target a different dialog.
    holder[0]=image;
    actions.addView(button("‹",()->{if(position[0]>0)showPicture(image,caption,photos,--position[0]);}),new LinearLayout.LayoutParams(0,dp(48),1));
    actions.addView(button("Сохранить",()->savePicture(photos.get(position[0]))),new LinearLayout.LayoutParams(0,dp(48),2));
    actions.addView(button("Удалить",()->track(new AlertDialog.Builder(a).setTitle("Удалить из этой галереи?").setMessage("Картинка также исчезнет из локального архива этой игры. Сайт Perchance не изменится.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{PlayerStore.Picture p=photos.get(position[0]);c.io.execute(()->{try{c.store.deleteImage(page,p.id);thumbs.remove(p.id);ui(()->c.say("Картинка удалена. Откройте галерею снова, чтобы обновить список."));}catch(Exception e){ui(()->c.say(e.getMessage()));}});}).create()).show()),new LinearLayout.LayoutParams(0,dp(48),2));
    actions.addView(button("›",()->{if(position[0]+1<photos.size())showPicture(image,caption,photos,++position[0]);}),new LinearLayout.LayoutParams(0,dp(48),1));root.addView(actions);root.addView(image,new LinearLayout.LayoutParams(-1,0,1));root.addView(caption);full("Иллюстрации",root);showPicture(image,caption,photos,start);
  }
  private void showPicture(ZoomImageView image,TextView caption,List<PlayerStore.Picture> photos,int index){PlayerStore.Picture p=photos.get(index);image.setTag(p.id);caption.setText((index+1)+" / "+photos.size()+" · "+p.caption);c.io.execute(()->{Bitmap b=decode(c.store.imageFile(p.id),2048);ui(()->{if(p.id.equals(image.getTag())){image.bitmap(b);if(b==null)c.say("Файл изображения недоступен");}});});}
  void archive(){String page=c.game();c.io.execute(()->{try{List<PlayerStore.Scene> scenes=c.store.summaries(page);ui(()->{LinearLayout root=column();root.addView(button("Экспорт истории в HTML",()->saveArchive(page)));if(scenes.isEmpty())root.addView(text("Архив пока пуст. Он сохраняет прочитанные сцены отдельно от игровых сейвов.",16));else{ListView list=new ListView(a);String[] labels=new String[scenes.size()];for(int i=0;i<labels.length;i++){PlayerStore.Scene s=scenes.get(i);labels[i]=s.title+"\n"+DateFormat.format("dd.MM HH:mm",s.created)+" · картинок: "+s.images.length();}list.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_list_item_1,labels));list.setOnItemClickListener((v,item,n,id)->c.io.execute(()->{try{PlayerStore.Scene scene=c.store.scene(scenes.get(n).id);if(scene!=null)ui(()->showScene(scene));}catch(Exception e){ui(()->c.say(e.getMessage()));}}));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));}full("Архив сцен · "+scenes.size(),root);});}catch(Exception e){ui(()->c.say(e.getMessage()));}});}
  private void showScene(PlayerStore.Scene s){reading=s;LinearLayout content=column();reader=full(s.title,content);layoutScene(content,s);}
  private void layoutScene(LinearLayout root,PlayerStore.Scene scene){root.removeAllViews();boolean landscape=a.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE;LinearLayout body=new LinearLayout(a);body.setOrientation(landscape?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(a);TextView narrative=text(scene.body,18);narrative.setTextIsSelectable(true);narrative.setLineSpacing(dp(3),1.1f);scroll.addView(narrative);body.addView(scroll,landscape?new LinearLayout.LayoutParams(0,-1,1):new LinearLayout.LayoutParams(-1,0,1));
    LinearLayout images=column();ScrollView pictureScroll=new ScrollView(a);pictureScroll.addView(images);if(scene.images.length()>0){body.addView(pictureScroll,landscape?new LinearLayout.LayoutParams(0,-1,1):new LinearLayout.LayoutParams(-1,0,1));for(int i=0;i<scene.images.length();i++){String id=scene.images.optString(i);ImageView image=new ImageView(a);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Иллюстрация сцены");images.addView(image,new LinearLayout.LayoutParams(-1,-2));c.io.execute(()->{Bitmap b=decode(c.store.imageFile(id),1200);ui(()->image.setImageBitmap(b));});}}
    root.addView(body,new LinearLayout.LayoutParams(-1,0,1));root.addView(button("Удалить сцену из архива",()->track(new AlertDialog.Builder(a).setTitle("Удалить сцену?").setMessage("Картинки останутся в галерее, игра на Perchance не изменится.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{c.io.execute(()->c.store.deleteScene(scene.id));reader.dismiss();}).create()).show()));
    root.setTag("scene-content");
  }
  void configuration(){if(reader!=null&&reader.isShowing()&&reading!=null){View content=reader.getWindow().getDecorView().findViewWithTag("scene-content");if(content instanceof LinearLayout)layoutScene((LinearLayout)content,reading);}}
  void commands(){try{JSONArray list=c.commands();String[] labels=new String[list.length()];for(int i=0;i<labels.length;i++)labels[i]=list.getJSONObject(i).optString("name");track(new AlertDialog.Builder(a).setTitle("Быстрые команды").setItems(labels,(d,n)->{try{command(list,n);}catch(Exception e){c.say(e.getMessage());}}).setPositiveButton("Добавить",(d,w)->editCommand(list,-1)).setNegativeButton("Закрыть",null).create()).show();}catch(Exception e){c.say("Не удалось прочитать команды");}}
  private EditText edit(String hint,String value,int max,boolean multi){EditText input=new EditText(a);input.setHint(hint);input.setContentDescription(hint);input.setText(value);input.setSingleLine(!multi);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});if(multi){input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setMinLines(3);input.setMaxLines(8);}return input;}
  private void command(JSONArray list,int index)throws Exception{JSONObject item=list.getJSONObject(index);String template=item.getString("text");String[] fields=PlayerPolicy.fields(template);LinearLayout body=column();body.setPadding(dp(14),dp(8),dp(14),dp(8));TextView preview=text(template,16);body.addView(preview);Map<String,EditText> inputs=new LinkedHashMap<>();for(String f:fields){EditText input=edit(f,"",500,false);body.addView(input);inputs.put(f,input);}ScrollView scroll=new ScrollView(a);scroll.addView(body);AlertDialog d=track(new AlertDialog.Builder(a).setTitle(item.getString("name")).setView(scroll).setPositiveButton("Вставить",null).setNeutralButton("Изменить",(x,w)->editCommand(list,index)).setNegativeButton("Закрыть",null).create());d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{try{Map<String,String> values=new HashMap<>();inputs.forEach((key,input)->values.put(key,input.getText().toString()));c.insert(PlayerPolicy.expand(template,values));d.dismiss();}catch(Exception e){preview.setText(e.getMessage());}}));d.show();}
  private void editCommand(JSONArray list,int index){if(index<0&&list.length()>=100){c.say("В наборе уже 100 команд");return;}try{JSONObject item=index<0?new JSONObject():list.getJSONObject(index);LinearLayout body=column();body.setPadding(dp(18),dp(8),dp(18),dp(8));EditText name=edit("Название команды",item.optString("name"),60,false),value=edit("Текст команды",item.optString("text"),4000,true);body.addView(name);body.addView(value);body.addView(text("Можно использовать поля: Осмотреть {предмет}, обращая внимание на {деталь}.",14));AlertDialog d=track(new AlertDialog.Builder(a).setTitle(index<0?"Новая команда":"Изменить команду").setView(body).setPositiveButton("Сохранить",null).setNeutralButton(index<0?"Отмена":"Удалить",(x,w)->{if(index>=0){list.remove(index);c.commands(list);}}).setNegativeButton("Закрыть",null).create());d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{if(name.getText().toString().trim().isEmpty()){name.setError("Введите название");return;}if(value.getText().toString().trim().isEmpty()){value.setError("Введите текст");return;}try{JSONObject entry=new JSONObject().put("name",name.getText().toString().trim()).put("text",value.getText().toString().trim());if(index<0)list.put(entry);else list.put(index,entry);c.commands(list);d.dismiss();}catch(Exception e){c.say(e.getMessage());}}));d.show();}catch(Exception e){c.say(e.getMessage());}}
  private void settings(){LinearLayout body=column();body.setPadding(dp(12),dp(8),dp(12),dp(8));body.addView(text(c.connected()?"Адаптер подключён к открытой игре":"Ожидаем подключения адаптера. Для неизвестных интерфейсов доступны копирование команд и ручное ожидание.",14));String[][] options={{"archive","Архивировать сцены"},{"gallery","Сохранять иллюстрации"},{"signal","Сигнал готовности"},{"background","Дожидаться генерации при сворачивании"}};for(String[] option:options){CheckBox check=new CheckBox(a);check.setText(option[1]);check.setMinHeight(dp(48));check.setChecked(c.enabled(option[0]));check.setOnCheckedChangeListener((v,checked)->c.setting(option[0],checked));body.addView(check);}body.addView(button("Разрешить уведомления",c::requestNotifications));body.addView(button("Ориентация экрана",()->track(new AlertDialog.Builder(a).setTitle("Ориентация экрана").setSingleChoiceItems(new String[]{"Как в настройках телефона","Вертикально","Горизонтально"},c.prefs.getInt("orientation",0),(d,n)->{c.orientation(n);d.dismiss();}).setNegativeButton("Закрыть",null).create()).show()));body.addView(text("Архив хранится только на телефоне и не заменяет игровые сохранения. Фон поддерживает сворачивание, пока процесс приложения остаётся живым.",13));ScrollView scroll=new ScrollView(a);scroll.addView(body);track(new AlertDialog.Builder(a).setTitle("Настройки панели APK").setView(scroll).setPositiveButton("Готово",null).create()).show();}
  private void savePicture(PlayerStore.Picture p){c.prefs.edit().putString("exportImage",p.id).putString("exportMime",p.mime).apply();Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(p.mime).putExtra(Intent.EXTRA_TITLE,"game-broth-"+p.id.substring(0,10)+(p.mime.equals("image/jpeg")?".jpg":p.mime.equals("image/webp")?".webp":".png"));try{a.startActivityForResult(intent,SAVE_IMAGE);}catch(Exception e){c.say("Не удалось открыть сохранение файла");}}
  private void saveArchive(String game){c.prefs.edit().putString("exportArchive",game).apply();try{a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/html").putExtra(Intent.EXTRA_TITLE,"game-broth-archive.html"),SAVE_ARCHIVE);}catch(Exception e){c.say("Не удалось открыть сохранение архива");}}
  boolean result(int code,int result,Intent data){if(code!=SAVE_IMAGE&&code!=SAVE_ARCHIVE)return false;String id=c.prefs.getString("exportImage",""),game=c.prefs.getString("exportArchive","");c.prefs.edit().remove("exportImage").remove("exportMime").remove("exportArchive").apply();if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return true;Uri destination=data.getData();c.io.execute(()->{try(OutputStream out=a.getContentResolver().openOutputStream(destination)){if(out==null)throw new IOException("Файл недоступен");if(code==SAVE_ARCHIVE){if(PlayerPolicy.page(game)==null)throw new IOException("Не найдена игра архива");c.store.exportArchive(game,out);}else try(InputStream in=new FileInputStream(c.store.imageFile(id))){byte[] bytes=new byte[16384];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}ui(()->c.say("Файл сохранён"));}catch(Exception e){ui(()->c.say("Не удалось записать файл: "+e.getMessage()));}});return true;}
  void close(){closed=true;for(Dialog d:new ArrayList<>(dialogs))d.dismiss();dialogs.clear();thumbs.evictAll();}
}
